export type ParsedAdvanceInstruction<
  TProgram extends string = typeof INTENT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    intent: TAccountMetas[0];
    board: TAccountMetas[1];
    owner: TAccountMetas[2];
    nextWorker?: TAccountMetas[3] | undefined;
    entry0?: TAccountMetas[4] | undefined;
    entry1?: TAccountMetas[5] | undefined;
    entry2?: TAccountMetas[6] | undefined;
    entry3?: TAccountMetas[7] | undefined;
    dropper?: TAccountMetas[8] | undefined;
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: AdvanceInstructionData;
};

export function parseAdvanceInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAdvanceInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === INTENT_ENGINE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      intent: getNextAccount(),
      board: getNextAccount(),
      owner: getNextAccount(),
      nextWorker: getNextOptionalAccount(),
      entry0: getNextOptionalAccount(),
      entry1: getNextOptionalAccount(),
      entry2: getNextOptionalAccount(),
      entry3: getNextOptionalAccount(),
      dropper: getNextOptionalAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getAdvanceInstructionDataDecoder().decode(instruction.data),
  };
}
